content:
/* Adventure Log checklist page */

.al-top {
  display: grid;
  gap: 20px;
  margin-top: 28px;
}
@media (min-width: 960px) {
  .al-top {
    grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);
    align-items: start;
  }
}

.al-progress {
  display: grid;
  gap: 16px;
  align-content: start;
  padding: 24px;
  border-radius: calc(var(--radius) + 6px);
  border: 1px solid var(--line);
  background: radial-gradient(120% 140% at 0% 0%, var(--accent-soft), transparent 55%), var(--surface);
}
@media (min-width: 960px) {
  .al-progress {
    position: sticky;
    top: 88px;
  }
}
.al-progress-num {
  display: flex;
  align-items: baseline;
  gap: 10px;
  font-family: var(--font-display);
}
.al-progress-num strong {
  font-size: clamp(2.6rem, 6vw, 3.6rem);
  line-height: 1;
  color: var(--accent-text);
}
.al-progress-num span {
  color: var(--ink-2);
}
.al-next {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 14px;
  margin: 0;
  color: var(--ink-2);
}
.al-next strong {
  color: var(--ink);
  font-family: var(--font-display);
  flex: 1 1 220px;
}

.al-rail h2 {
  font-size: 1.05rem;
  font-family: var(--font-display);
  margin: 0 0 12px;
}
.al-rail ol {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}
.al-rail button {
  width: 100%;
  display: grid;
  grid-template-columns: 30px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 9px 12px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition: transform 0.3s var(--ease-out), border-color 0.25s var(--ease-out), background-color 0.25s;
}
.al-rail button:hover {
  transform: translateX(4px);
  border-color: color-mix(in oklch, var(--accent) 45%, var(--line));
}
.al-rail button:active {
  transform: translateX(4px) scale(0.99);
}
.al-rail-n {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent-text);
  font-family: var(--font-display);
  font-weight: 700;
}
.al-rail-count {
  color: var(--ink-3);
  font-size: 0.88rem;
}

.al-tools {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 36px;
}
.al-tools .seg button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--on-accent);
}

.al-list {
  display: grid;
  gap: 14px;
  margin-top: 16px;
  padding-bottom: 72px;
}

.al-log {
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 4px);
  background: var(--surface);
  scroll-margin-top: 96px;
}
.al-log[data-done="true"] {
  border-color: color-mix(in oklch, var(--accent) 55%, var(--line));
}

.al-log-head {
  width: 100%;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  background: none;
  border: 0;
  color: var(--ink);
  font: inherit;
  text-align: left;
  cursor: pointer;
  border-radius: inherit;
}
.al-log-icon {
  display: grid;
  place-items: center;
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: var(--surface-2);
  color: var(--accent-text);
}
.al-log-title strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.12rem;
}
.al-log-title small {
  display: block;
  margin-top: 2px;
  color: var(--ink-2);
  font-size: 0.9rem;
  line-height: 1.45;
}
.al-log-meta {
  display: flex;
  align-items: center;
  gap: 10px;
}
.al-log-count {
  font-family: var(--font-display);
  font-weight: 600;
  min-width: 3.2em;
  text-align: right;
}
.al-caret {
  transition: transform 0.35s var(--ease-out);
  color: var(--ink-3);
}
.al-log-head[aria-expanded="true"] .al-caret {
  transform: rotate(180deg);
}
.al-effort {
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 0.8rem;
  border: 1px solid var(--line);
  color: var(--ink-2);
  white-space: nowrap;
}
.al-effort[data-e="3"] {
  border-color: color-mix(in oklch, var(--accent) 50%, var(--line));
  color: var(--accent-text);
}

.al-log-body {
  padding: 0 18px 18px;
}
@media (prefers-reduced-motion: no-preference) {
  .al-log-body {
    animation: rise 0.45s var(--ease-out) both;
  }
  .al-vol-body[open] .al-how {
    animation: rise 0.35s var(--ease-out) both;
  }
}

.al-facts {
  display: grid;
  gap: 10px 24px;
  margin: 0 0 14px;
  padding: 14px 16px;
  border-radius: var(--radius);
  background: var(--bg);
}
@media (min-width: 720px) {
  .al-facts {
    grid-template-columns: 1fr 1fr;
  }
  .al-facts-wide {
    grid-column: 1 / -1;
  }
}
.al-facts dt {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-3);
  font-size: 0.84rem;
}
.al-facts dd {
  margin: 2px 0 0;
  line-height: 1.5;
}
.al-total {
  color: var(--accent-text);
  font-family: var(--font-display);
  font-weight: 600;
}
.al-note {
  margin: 0 0 14px;
}

.al-log-actions {
  display: flex;
  gap: 16px;
  margin-bottom: 6px;
}
.link-btn {
  background: none;
  border: 0;
  padding: 4px 0;
  color: var(--accent-text);
  font: inherit;
  font-size: 0.9rem;
  cursor: pointer;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 3px;
  transition: text-decoration-color 0.25s;
}
.link-btn:hover {
  text-decoration-color: currentColor;
}

.al-vols {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
}
.al-vol {
  display: grid;
  grid-template-columns: 28px 1fr;
  gap: 12px;
  align-items: start;
  padding: 10px 0;
  border-top: 1px solid color-mix(in oklch, var(--line) 55%, transparent);
  scroll-margin-top: 120px;
}
.al-vol:first-child {
  border-top: 0;
}

.tick {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin-top: 2px;
  padding: 0;
  border-radius: 7px;
  border: 1.5px solid var(--ink-3);
  background: transparent;
  color: var(--on-accent);
  cursor: pointer;
  transition: background-color 0.2s, border-color 0.2s, transform 0.2s var(--ease-out);
}
.tick:hover {
  border-color: var(--accent);
}
.tick:active {
  transform: scale(0.9);
}
.tick[data-on="true"] {
  background: var(--accent);
  border-color: var(--accent);
}

.al-vol-body summary {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px 12px;
  cursor: pointer;
  list-style: none;
}
.al-vol-body summary::-webkit-details-marker {
  display: none;
}
.al-vol-title {
  font-weight: 500;
  flex: 1 1 260px;
  transition: color 0.2s;
}
.al-vol-body summary:hover .al-vol-title {
  color: var(--accent-text);
}
.al-vol-title::after {
  content: " +";
  color: var(--ink-3);
}
.al-vol-body[open] .al-vol-title::after {
  content: " -";
}
.al-vol[data-on="true"] .al-vol-title {
  color: var(--ink-3);
  text-decoration: line-through;
  text-decoration-color: var(--ink-3);
}
.al-reward {
  font-size: 0.86rem;
  color: var(--ink-2);
  padding: 2px 10px;
  border-radius: 999px;
  background: var(--surface-2);
}
.al-reward-stat {
  background: var(--accent-soft);
  color: var(--accent-text);
  font-weight: 600;
}
.al-how {
  margin: 10px 0 4px;
  padding-left: 18px;
  display: grid;
  gap: 6px;
  color: var(--ink-2);
  line-height: 1.55;
  max-width: 78ch;
}

.al-src {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid color-mix(in oklch, var(--line) 55%, transparent);
  font-size: 0.86rem;
  color: var(--ink-3);
}
.al-src a {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

@media (max-width: 599px) {
  .al-log-head {
    grid-template-columns: auto 1fr;
  }
  .al-log-meta {
    grid-column: 1 / -1;
    justify-content: flex-start;
  }
  .al-log-icon {
    width: 44px;
    height: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .al-rail button:hover,
  .al-rail button:active {
    transform: none;
  }
}

.topic-cta {
  margin-top: 16px;
  margin-left: 12px;
}
@media (max-width: 599px) {
  .topic-cta {
    margin-left: 0;
  }
}

/* steps with location + NPC */
.al-steps {
  margin: 12px 0 4px;
  padding: 0;
  list-style: none;
  counter-reset: st;
  display: grid;
  gap: 10px;
  max-width: 84ch;
}
.al-steps li {
  counter-increment: st;
  display: grid;
  gap: 4px;
  padding: 10px 12px 10px 40px;
  position: relative;
  border-radius: var(--radius);
  background: var(--bg);
  transition: background-color 0.25s var(--ease-out), transform 0.3s var(--ease-out);
}
.al-steps li::before {
  content: counter(st);
  position: absolute;
  left: 10px;
  top: 10px;
  width: 20px;
  height: 20px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  background: var(--accent-soft);
  color: var(--accent-text);
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: 700;
}
@media (hover: hover) {
  .al-steps li:hover {
    background: var(--surface-2);
    transform: translateX(3px);
  }
}
.al-step-do {
  color: var(--ink);
  line-height: 1.5;
}
.al-step-at,
.al-step-npc {
  display: flex;
  gap: 6px;
  align-items: baseline;
  font-size: 0.88rem;
  line-height: 1.5;
  color: var(--ink-2);
}
.al-step-at svg,
.al-step-npc svg {
  flex: none;
  position: relative;
  top: 2px;
  color: var(--accent-text);
}
.al-step-npc {
  color: var(--ink-3);
}

/* video cards */
.al-media {
  margin-top: 18px;
}
.al-media h3 {
  margin: 0 0 10px;
  font-family: var(--font-display);
  font-size: 1rem;
}
.al-videos {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
}
.al-videos-sm {
  grid-template-columns: repeat(auto-fill, minmax(170px, 240px));
  margin-top: 10px;
}
.al-video {
  display: grid;
  gap: 8px;
  text-decoration: none;
  color: var(--ink);
}
.al-thumb {
  position: relative;
  display: block;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  border-radius: var(--radius);
  background: var(--surface-2);
  border: 1px solid var(--line);
}
.al-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.5s var(--ease-out), filter 0.3s;
  filter: saturate(0.9);
}
.al-play {
  position: absolute;
  inset: 0;
  margin: auto;
  color: oklch(0.98 0.01 265 / 0.92);
  filter: drop-shadow(0 4px 12px oklch(0.1 0.04 265 / 0.6));
  transition: transform 0.4s var(--spring), color 0.25s;
}
.al-video-title {
  font-size: 0.88rem;
  line-height: 1.4;
  color: var(--ink-2);
  transition: color 0.2s;
}
@media (hover: hover) {
  .al-video:hover .al-thumb img {
    transform: scale(1.05);
    filter: saturate(1.1);
  }
  .al-video:hover .al-play {
    transform: scale(1.12);
    color: var(--accent);
  }
  .al-video:hover .al-video-title {
    color: var(--accent-text);
  }
}
.al-video:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 4px;
  border-radius: var(--radius);
}
.al-photos {
  margin-top: 12px;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  color: var(--ink);
  text-decoration: none;
  transition: border-color 0.25s, transform 0.3s var(--ease-out);
}
.al-photos svg:first-child {
  color: var(--accent-text);
}
.al-photos strong {
  display: block;
  font-family: var(--font-display);
  font-size: 0.95rem;
}
.al-photos small {
  display: block;
  color: var(--ink-3);
  font-size: 0.82rem;
}
.al-photos:hover {
  border-color: color-mix(in oklch, var(--accent) 50%, var(--line));
  transform: translateY(-2px);
}
@media (prefers-reduced-motion: reduce) {
  .al-video:hover .al-thumb img,
  .al-video:hover .al-play,
  .al-photos:hover,
  .al-steps li:hover {
    transform: none;
  }
}

/* Northern-east heroic design tokens.
   Surface: kram indigo (Isan indigo-dyed cotton). One accent: turmeric saffron. */

:root {
  --font-display: "Chakra Petch", "IBM Plex Sans Thai", system-ui, sans-serif;
  --font-body: "IBM Plex Sans Thai", system-ui, sans-serif;

  --radius: 10px;
  --radius-pill: 999px;

  --z-sticky: 10;
  --z-overlay: 20;

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);

  /* dark (default) */
  --bg: oklch(0.17 0.035 265);
  --surface: oklch(0.205 0.04 265);
  --surface-2: oklch(0.245 0.045 265);
  --line: oklch(0.33 0.04 265);
  --ink: oklch(0.95 0.01 265);
  --ink-2: oklch(0.79 0.025 265);
  --ink-3: oklch(0.68 0.03 265);
  --accent: oklch(0.79 0.15 68);
  --accent-hover: oklch(0.84 0.14 72);
  --accent-text: oklch(0.82 0.14 70);
  --on-accent: oklch(0.19 0.04 265);
  --accent-soft: oklch(0.79 0.15 68 / 0.14);
  --pattern: oklch(0.95 0.01 265 / 0.045);
  --shadow: 0 20px 50px oklch(0.08 0.04 265 / 0.55);
  color-scheme: dark;
}

:root[data-theme="light"] {
  --bg: oklch(0.975 0.006 265);
  --surface: oklch(0.995 0.003 265);
  --surface-2: oklch(0.945 0.012 265);
  --line: oklch(0.87 0.02 265);
  --ink: oklch(0.22 0.045 265);
  --ink-2: oklch(0.4 0.04 265);
  --ink-3: oklch(0.48 0.035 265);
  --accent: oklch(0.77 0.15 66);
  --accent-hover: oklch(0.72 0.15 62);
  --accent-text: oklch(0.5 0.14 50);
  --on-accent: oklch(0.2 0.045 265);
  --accent-soft: oklch(0.77 0.15 66 / 0.18);
  --pattern: oklch(0.22 0.045 265 / 0.05);
  --shadow: 0 20px 50px oklch(0.4 0.05 265 / 0.16);
  color-scheme: light;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
    --bg: oklch(0.975 0.006 265);
    --surface: oklch(0.995 0.003 265);
    --surface-2: oklch(0.945 0.012 265);
    --line: oklch(0.87 0.02 265);
    --ink: oklch(0.22 0.045 265);
    --ink-2: oklch(0.4 0.04 265);
    --ink-3: oklch(0.48 0.035 265);
    --accent: oklch(0.77 0.15 66);
    --accent-hover: oklch(0.72 0.15 62);
    --accent-text: oklch(0.5 0.14 50);
    --on-accent: oklch(0.2 0.045 265);
    --accent-soft: oklch(0.77 0.15 66 / 0.18);
    --pattern: oklch(0.22 0.045 265 / 0.05);
    --shadow: 0 20px 50px oklch(0.4 0.05 265 / 0.16);
    color-scheme: light;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 84px;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1,
h2,
h3,
h4 {
  font-family: var(--font-display);
  line-height: 1.15;
  margin: 0;
  text-wrap: balance;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
  text-wrap: pretty;
}

a {
  color: inherit;
}

img {
  display: block;
  max-width: 100%;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 6px;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 16px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 32px;
  }
}

.num {
  font-family: var(--font-display);
  font-variant-numeric: tabular-nums;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 22px;
  border-radius: var(--radius-pill);
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background-color 0.25s var(--ease-out), transform 0.2s var(--ease-out),
    border-color 0.25s var(--ease-out);
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn-primary {
  background: var(--accent);
  color: var(--on-accent);
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line);
}

.btn-ghost:hover {
  border-color: var(--ink-3);
  background: var(--surface-2);
}

/* ---------- Nav ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: var(--z-sticky);
  background: color-mix(in oklch, var(--bg) 86%, transparent);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid color-mix(in oklch, var(--line) 60%, transparent);
}

.nav-inner {
  height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.02em;
  font-size: 1.05rem;
  white-space: nowrap;
}

.brand-mark {
  width: 32px;
  height: 32px;
  flex: none;
}

.nav-links {
  display: none;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-links a {
  display: block;
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  text-decoration: none;
  color: var(--ink-2);
  font-size: 0.95rem;
  transition: color 0.2s, background-color 0.2s;
}

.nav-links a:hover {
  color: var(--ink);
  background: var(--surface-2);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.icon-btn {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.icon-btn:hover {
  background: var(--surface-2);
}

.nav-cta {
  display: none;
}

@media (min-width: 960px) {
  .nav-links {
    display: flex;
  }
  .nav-cta {
    display: inline-flex;
    min-height: 42px;
    padding: 0 18px;
  }
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 40px 0 56px;
  overflow: hidden;
}

.hero::before {
  /* mudmee-like woven texture, decorative only */
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
      45deg,
      var(--pattern) 0 2px,
      transparent 2px 22px
    ),
    repeating-linear-gradient(-45deg, var(--pattern) 0 2px, transparent 2px 22px);
  mask-image: linear-gradient(to bottom, black 0%, transparent 85%);
  pointer-events: none;
}

.hero-grid {
  position: relative;
  display: grid;
  gap: 36px;
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  color: var(--accent-text);
  font-weight: 600;
  margin-bottom: 18px;
}

.hero h1 {
  font-size: clamp(2.2rem, 5.2vw, 4rem);
  font-weight: 700;
  line-height: 1.12;
}

.hero h1 .line {
  display: block;
  white-space: nowrap;
}

.hero h1 em {
  font-style: normal;
  color: var(--accent-text);
}

/* live mini calculator in hero */
.quick {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface);
  box-shadow: var(--shadow);
  padding: 26px;
}

.quick-head {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 600;
  color: var(--ink);
}

.quick-head svg {
  color: var(--accent-text);
}

.quick-label {
  display: flex;
  justify-content: space-between;
  margin-top: 24px;
  color: var(--ink-2);
  font-size: 0.95rem;
}

.quick-label strong {
  color: var(--ink);
  font-size: 1.1rem;
}

.quick-range {
  width: 100%;
  margin-top: 10px;
  accent-color: var(--accent);
  height: 28px;
  cursor: pointer;
}

.quick-out {
  margin-top: 18px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  color: var(--ink-2);
}

.quick-out strong {
  font-size: clamp(2.6rem, 6vw, 3.6rem);
  line-height: 1;
  color: var(--accent-text);
}

.hero-sub {
  margin-top: 20px;
  font-size: 1.125rem;
  color: var(--ink-2);
  max-width: 46ch;
}

.hero-ctas {
  margin-top: 32px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.hero-visual {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4 / 3;
  box-shadow: var(--shadow);
  border: 1px solid var(--line);
}

.hero-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, transparent 40%, oklch(0.17 0.035 265 / 0.55));
}

@media (min-width: 900px) {
  .hero {
    padding: 72px 0 96px;
  }
  .hero-grid {
    grid-template-columns: 1.08fr 0.92fr;
    gap: 56px;
  }
  .hero-visual {
    aspect-ratio: 5 / 6;
  }
}

/* ---------- Stat strip (under hero) ---------- */
.facts {
  border-block: 1px solid var(--line);
  background: var(--surface);
}

.facts-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
}

.fact {
  padding: 22px 16px;
}

.fact + .fact {
  border-left: 1px solid var(--line);
}

.fact:nth-child(3) {
  border-left: none;
}

.fact strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--ink);
}

.fact span {
  color: var(--ink-2);
  font-size: 0.92rem;
}

@media (max-width: 767px) {
  .fact:nth-child(n + 3) {
    border-top: 1px solid var(--line);
  }
}

@media (min-width: 768px) {
  .facts-grid {
    grid-template-columns: repeat(4, 1fr);
  }
  .fact:nth-child(3) {
    border-left: 1px solid var(--line);
  }
  .fact {
    padding: 28px 24px;
  }
}

/* ---------- Sections ---------- */
.section {
  padding: 72px 0;
}

@media (min-width: 900px) {
  .section {
    padding: 112px 0;
  }
}

.section-head {
  max-width: 62ch;
  margin-bottom: 40px;
}

.section-head h2 {
  font-size: clamp(1.8rem, 3.6vw, 2.75rem);
  font-weight: 700;
}

.section-head p {
  margin-top: 14px;
  color: var(--ink-2);
  font-size: 1.05rem;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .reveal {
      animation: reveal-up linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 40%;
    }
  }
}

@keyframes reveal-up {
  from {
    opacity: 0.2;
    transform: translateY(28px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* ---------- Workbench ---------- */
.bench {
  display: grid;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;
}

.bench-tabs {
  display: flex;
  gap: 6px;
  padding: 10px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  scrollbar-width: none;
}

.bench-tab {
  position: relative;
  scroll-snap-align: start;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--font-body);
  font-size: 0.95rem;
  white-space: nowrap;
  cursor: pointer;
  text-align: left;
}

.bench-tab:hover {
  color: var(--ink);
}

.bench-tab[aria-selected="true"] {
  color: var(--ink);
}

.bench-tab-bg {
  position: absolute;
  inset: 0;
  border-radius: var(--radius);
  background: var(--surface);
  border: 1px solid var(--line);
  z-index: 0;
}

.bench-tab > span,
.bench-tab > svg {
  position: relative;
  z-index: 1;
}

.bench-tab svg {
  color: var(--accent-text);
}

.bench-panel {
  padding: 24px 16px 28px;
  min-height: 420px;
}

@media (min-width: 900px) {
  .bench {
    grid-template-columns: 250px 1fr;
  }
  .bench-tabs {
    flex-direction: column;
    border-bottom: 0;
    border-right: 1px solid var(--line);
    padding: 14px;
    overflow: visible;
  }
  .bench-tab {
    padding: 12px 14px;
  }
  .bench-panel {
    padding: 36px 40px 40px;
  }
}

.calc-title {
  font-size: 1.4rem;
  font-weight: 600;
}

.calc-desc {
  margin-top: 6px;
  color: var(--ink-2);
  max-width: 60ch;
}

.calc-grid {
  margin-top: 28px;
  display: grid;
  gap: 28px;
}

@media (min-width: 1100px) {
  .calc-grid {
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }
}

.fields {
  display: grid;
  gap: 18px;
  align-content: start;
}

.field {
  display: grid;
  gap: 8px;
}

.field label,
.field .label {
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--ink);
}

.field .help {
  font-size: 0.85rem;
  color: var(--ink-3);
}

.input,
.select {
  width: 100%;
  min-height: 46px;
  padding: 0 14px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-variant-numeric: tabular-nums;
}

.input::placeholder {
  color: var(--ink-3);
}

.input:focus,
.select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.input[aria-invalid="true"] {
  border-color: oklch(0.68 0.19 25);
}

.error {
  font-size: 0.85rem;
  color: oklch(0.72 0.17 25);
}

.row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.seg {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.seg button {
  min-height: 40px;
  padding: 0 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--font-body);
  font-size: 0.92rem;
  cursor: pointer;
}

.seg button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--on-accent);
  border-color: var(--accent);
  font-weight: 600;
}

.toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  cursor: pointer;
}

.toggle input {
  appearance: none;
  flex: none;
  width: 44px;
  height: 26px;
  border-radius: var(--radius-pill);
  background: var(--surface-2);
  border: 1px solid var(--line);
  position: relative;
  cursor: pointer;
  transition: background-color 0.2s;
}

.toggle input::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--ink-3);
  transition: transform 0.25s var(--ease-out), background-color 0.2s;
}

.toggle input:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.toggle input:checked::after {
  transform: translateX(18px);
  background: var(--on-accent);
}

.toggle small {
  display: block;
  color: var(--ink-3);
  font-size: 0.84rem;
}

/* results */
.result {
  border-radius: var(--radius);
  background: var(--bg);
  border: 1px solid var(--line);
  padding: 24px;
  align-self: start;
}

.result-main .k {
  color: var(--ink-2);
  font-size: 0.92rem;
}

.result-main .v {
  display: block;
  font-family: var(--font-display);
  font-variant-numeric: tabular-nums;
  font-size: clamp(2.2rem, 5vw, 3.2rem);
  font-weight: 700;
  line-height: 1.1;
  color: var(--accent-text);
  margin-top: 4px;
}

.result-main .v small {
  font-size: 0.45em;
  color: var(--ink-2);
  font-weight: 500;
  margin-left: 6px;
}

.result-list {
  margin: 20px 0 0;
  padding: 18px 0 0;
  border-top: 1px solid var(--line);
  display: grid;
  gap: 12px;
}

.result-list div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.result-list dt {
  color: var(--ink-2);
  font-size: 0.94rem;
}

.result-list dd {
  margin: 0;
  font-family: var(--font-display);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  text-align: right;
}

.note {
  margin-top: 16px;
  display: flex;
  gap: 10px;
  font-size: 0.86rem;
  color: var(--ink-3);
}

.note svg {
  flex: none;
  margin-top: 3px;
}

/* ---------- Roadmap ---------- */
.roadmap {
  display: grid;
  gap: 40px;
}

@media (min-width: 900px) {
  .roadmap {
    grid-template-columns: 0.8fr 1.2fr;
    gap: 72px;
  }
  .roadmap-intro {
    position: sticky;
    top: 110px;
    align-self: start;
  }
}

.budget {
  margin-top: 28px;
  padding: 22px;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--on-accent);
}

.budget strong {
  display: block;
  font-family: var(--font-display);
  font-size: 2.4rem;
  line-height: 1.1;
}

.budget p {
  margin-top: 6px;
  font-size: 0.95rem;
}

.phases {
  list-style: none;
  margin: 0;
  padding: 0;
  counter-reset: phase;
}

.phase {
  position: relative;
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 18px;
  padding-bottom: 36px;
}

.phase:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 27px;
  top: 56px;
  bottom: 0;
  width: 1px;
  background: var(--line);
}

.phase-num {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  background: var(--surface);
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--accent-text);
}

.phase h3 {
  font-size: 1.25rem;
  margin-top: 12px;
}

.phase .when {
  color: var(--ink-3);
  font-size: 0.9rem;
}

.phase ul {
  margin: 12px 0 0;
  padding-left: 1.1em;
  color: var(--ink-2);
  display: grid;
  gap: 6px;
}

/* ---------- Free bento ---------- */
.bento {
  display: grid;
  gap: 14px;
}

.tile {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface);
  padding: 26px;
  overflow: hidden;
  min-height: 220px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.tile h3 {
  font-size: 1.3rem;
}

.tile p {
  margin-top: 8px;
  color: var(--ink-2);
  max-width: 48ch;
}

.tile svg.tile-icon {
  position: absolute;
  top: 24px;
  left: 24px;
  color: var(--accent-text);
}

/* deep kram indigo with woven mudmee texture, same in both themes */
.tile-kram {
  min-height: 300px;
  border: 0;
  color: oklch(0.96 0.01 265);
  background-color: oklch(0.3 0.09 265);
  background-image: repeating-linear-gradient(45deg, oklch(1 0 0 / 0.07) 0 3px, transparent 3px 18px),
    repeating-linear-gradient(-45deg, oklch(1 0 0 / 0.07) 0 3px, transparent 3px 18px),
    radial-gradient(circle at 85% 15%, oklch(0.79 0.15 68 / 0.35), transparent 45%);
}

.tile-kram p {
  color: oklch(0.88 0.02 265);
}

.tile-kram svg.tile-icon {
  color: oklch(0.84 0.14 70);
}

@media (min-width: 900px) {
  .tile-kram {
    min-height: 320px;
  }
  .tile-kram h3 {
    font-size: 1.7rem;
  }
}

.tile-accent {
  background: var(--accent);
  color: var(--on-accent);
  border-color: var(--accent);
}

.tile-accent p {
  color: color-mix(in oklch, var(--on-accent) 82%, transparent);
}

.tile-accent svg.tile-icon {
  color: var(--on-accent);
}

.tile-pattern {
  background-color: var(--surface-2);
  background-image: repeating-linear-gradient(
    90deg,
    var(--pattern) 0 10px,
    transparent 10px 20px
  );
}

@media (min-width: 900px) {
  .bento {
    grid-template-columns: repeat(3, 1fr);
    grid-template-areas:
      "a a b"
      "c d e";
  }
  .tile:nth-child(1) {
    grid-area: a;
  }
  .tile:nth-child(2) {
    grid-area: b;
  }
  .tile:nth-child(3) {
    grid-area: c;
  }
  .tile:nth-child(4) {
    grid-area: d;
  }
  .tile:nth-child(5) {
    grid-area: e;
  }
}

/* ---------- Tips ---------- */
.tips {
  max-width: 820px;
}

.tip {
  border-bottom: 1px solid var(--line);
}

.tip summary {
  list-style: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  padding: 22px 0;
  cursor: pointer;
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 600;
}

.tip summary::-webkit-details-marker {
  display: none;
}

.tip summary svg {
  flex: none;
  color: var(--accent-text);
  transition: transform 0.3s var(--ease-out);
}

.tip[open] summary svg {
  transform: rotate(45deg);
}

.tip-body {
  padding: 0 0 24px;
  color: var(--ink-2);
  max-width: 68ch;
}

/* ---------- About + footer ---------- */
.about {
  display: grid;
  gap: 40px;
  align-items: center;
}

.about-panel {
  border-radius: var(--radius);
  aspect-ratio: 16 / 11;
  padding: 32px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  color: oklch(0.96 0.01 265);
  background-color: oklch(0.3 0.09 265);
  background-image: repeating-linear-gradient(90deg, oklch(1 0 0 / 0.06) 0 2px, transparent 2px 14px),
    repeating-linear-gradient(0deg, oklch(1 0 0 / 0.06) 0 2px, transparent 2px 14px);
}

.about-panel strong {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 6vw, 4.2rem);
  line-height: 1;
  letter-spacing: 0.01em;
}

.about-panel strong + strong {
  color: oklch(0.84 0.14 70);
}

.about-panel span {
  margin-top: 16px;
  color: oklch(0.88 0.02 265);
}

.about h2 {
  font-size: clamp(1.8rem, 3.6vw, 2.75rem);
}

.about p {
  margin-top: 16px;
  color: var(--ink-2);
  max-width: 58ch;
}

.games {
  margin-top: 24px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  font-size: 0.92rem;
  color: var(--ink-2);
}

.chip-on {
  border-color: var(--accent);
  color: var(--ink);
  background: var(--accent-soft);
}

@media (min-width: 900px) {
  .about {
    grid-template-columns: 1fr 1fr;
    gap: 72px;
  }
}

.footer {
  border-top: 1px solid var(--line);
  padding: 48px 0 40px;
  color: var(--ink-3);
  font-size: 0.9rem;
}

.footer-grid {
  display: grid;
  gap: 28px;
}

.footer h4 {
  font-size: 0.95rem;
  color: var(--ink);
  margin-bottom: 10px;
}

.footer ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 6px;
}

.footer a {
  color: var(--ink-2);
  text-decoration: none;
}

.footer a:hover {
  color: var(--ink);
  text-decoration: underline;
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: 1.4fr 1fr 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ---------- Nuxt port additions ---------- */
.bench-tab {
  transition: background-color 0.25s var(--ease-out), color 0.2s, box-shadow 0.25s var(--ease-out);
}

.bench-tab[aria-selected="true"] {
  background: var(--surface);
  box-shadow: inset 0 0 0 1px var(--line);
}

.spots {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 4px;
  counter-reset: spot;
}

.spots li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}

.spots li:last-child {
  border-bottom: 0;
}

.spots strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.05rem;
}

.spots span {
  display: block;
  font-size: 0.86rem;
  color: var(--ink-2);
}

.spots .spot-hint {
  color: var(--accent-text);
}

.spots b {
  flex: none;
  font-size: 1.15rem;
  color: var(--accent-text);
}

.spots b small {
  font-size: 0.75em;
  color: var(--ink-2);
  margin-left: 2px;
  font-weight: 500;
}

.spot-empty {
  color: var(--ink-2);
}

.note a {
  color: var(--accent-text);
}

/* ---------- Guide hub ---------- */
.guide {
  display: grid;
  gap: 24px;
}

.guide-tabs {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 4px;
}

.guide-tabs button {
  flex: none;
  min-height: 44px;
  padding: 0 18px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 0.98rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.guide-tabs button[aria-selected="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--on-accent);
}

.guide-body {
  display: grid;
  gap: 18px;
}

@media (min-width: 900px) {
  .guide-body {
    grid-template-columns: 1fr 1fr;
    gap: 22px;
  }
}

.guide-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  padding: 24px;
}

