// Collects bilingual (SEA English + Thai) data and icons from BDOCodex.
// Usage: node collect.mjs <manifest.json> <out.json> <publicDir>
import fs from "node:fs/promises";
import path from "node:path";

const [, , manifestPath, outPath, publicDir] = process.argv;
const manifest = JSON.parse(await fs.readFile(manifestPath, "utf8"));
const BASE = "https://bdocodex.com";
const UA = "Mozilla/5.0 (Northern-east heroic fan-site data refresh)";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function get(url) {
  for (let i = 0; i < 3; i++) {
    const r = await fetch(url, { headers: { "user-agent": UA } });
    if (r.ok) return r.text();
    await sleep(1000 * (i + 1));
  }
  throw new Error("fetch failed " + url);
}

const decode = (s) =>
  s
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .trim();
const stripTags = (s) => decode(s.replace(/<script[\s\S]*?<\/script>/g, " ").replace(/<[^>]+>/g, " ").replace(/\s+/g, " "));
const title = (html) => decode((html.match(/<title>([^<]*)<\/title>/) || [, ""])[1].replace(/ - BDO Codex$/, ""));

function descOf(html, lang) {
  const text = stripTags(html);
  const key = lang === "th" ? "คำอธิบาย" : "Description";
  const i = text.indexOf(key);
  if (i < 0) return "";
  let s = text.slice(i + key.length).replace(/^\s*:\s*/, "");
  const stops = ["Show/hide", "แสดง / ซ่อน", "Buy price", "ราคาซื้อ", "Knowledge:", "ความรู้:", "Production Method", "In-game market", "Item Exchange", "- Description", "Quest complete"];
  let end = s.length;
  for (const st of stops) {
    const j = s.indexOf(st);
    if (j > 0 && j < end) end = j;
  }
  return s.slice(0, Math.min(end, 280)).trim();
}

const icons = new Set();
const out = { generatedAt: new Date().toISOString(), source: BASE, items: {}, npcs: {}, quests: {} };

for (const id of manifest.items) {
  const rec = {};
  for (const lang of ["seaen", "th"]) {
    const html = await get(`${BASE}/${lang}/item/${id}/`);
    rec[lang] = { name: title(html), desc: descOf(html, lang === "th" ? "th" : "en") };
    if (lang === "seaen") {
      const icon = (html.match(/\/items\/new_icon\/[^"']+?\.webp/) || [null])[0];
      rec.icon = icon;
      if (icon) icons.add(icon);
      const sell = (html.match(/Sell price:\s*([\d,]+)/) || [, null])[1];
      const buy = (html.match(/Buy price:\s*([\d,]+)/) || [, null])[1];
      rec.sell = sell ? Number(sell.replace(/,/g, "")) : null;
      rec.buy = buy ? Number(buy.replace(/,/g, "")) : null;
    }
    await sleep(350);
  }
  rec.url = { en: `${BASE}/seaen/item/${id}/`, th: `${BASE}/th/item/${id}/` };
  out.items[id] = rec;
  console.log("item", id, rec.seaen.name, "|", rec.th.name);
}

for (const id of manifest.npcs) {
  const rec = {};
  for (const lang of ["seaen", "th"]) {
    const html = await get(`${BASE}/${lang}/npc/${id}/`);
    rec[lang] = { name: title(html) };
    if (lang === "seaen") {
      const art = (html.match(/\/items\/ui_artwork\/ic_[^"']+?\.webp/) || [null])[0];
      rec.art = art;
      if (art) icons.add(art);
      const lvl = (html.match(/Level:\s*(\d+)/) || [, null])[1];
      rec.level = lvl ? Number(lvl) : null;
    }
    await sleep(350);
  }
  rec.url = { en: `${BASE}/seaen/npc/${id}/`, th: `${BASE}/th/npc/${id}/` };
  out.npcs[id] = rec;
  console.log("npc", id, rec.seaen.name, "|", rec.th.name);
}

for (const qid of manifest.quests) {
  const rec = {};
  for (const lang of ["seaen", "th"]) {
    const html = await get(`${BASE}/${lang}/quest/${qid}/`);
    const text = stripTags(html);
    rec[lang] = { name: title(html), desc: descOf(html, lang === "th" ? "th" : "en") };
    if (lang === "seaen") {
      rec.level = Number((text.match(/Level:\s*(\d+)/) || [, 0])[1]);
      rec.region = (text.match(/Region:\s*(.+?)\s*Category:/) || [, ""])[1];
      rec.type = (text.match(/Type:\s*(.+?)\s*Level:/) || [, ""])[1];
      const icon = (html.match(/\/items\/(?:new_icon|quest)\/[^"']+?\.webp/) || [null])[0];
      rec.icon = icon;
      if (icon) icons.add(icon);
    }
    await sleep(350);
  }
  rec.url = { en: `${BASE}/seaen/quest/${qid}/`, th: `${BASE}/th/quest/${qid}/` };
  out.quests[qid] = rec;
  console.log("quest", qid, rec.seaen.name, "|", rec.th.name, "| Lv", rec.level);
}

// Download images into <publicDir>/codex/... preserving the codex path.
let n = 0;
for (const p of icons) {
  const dest = path.join(publicDir, "codex", p.replace(/^\/items\//, ""));
  try {
    await fs.access(dest);
    continue;
  } catch {}
  const r = await fetch(BASE + p, { headers: { "user-agent": UA } });
  if (!r.ok) {
    console.warn("icon failed", p, r.status);
    continue;
  }
  await fs.mkdir(path.dirname(dest), { recursive: true });
  await fs.writeFile(dest, Buffer.from(await r.arrayBuffer()));
  n++;
  await sleep(200);
}
console.log("downloaded icons:", n);
await fs.writeFile(outPath, JSON.stringify(out, null, 2));

// Collects current enhancement tables (base chance, material, Cron cost, durability loss)
// for the gear lines a new player meets, from BDOCodex item pages (enchantment_array).
// Usage (from site/): node scripts/codex-enhance.mjs
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const site = path.resolve(here, "..");
const BASE = "https://bdocodex.com";
const UA = { headers: { "user-agent": "Mozilla/5.0 (Northern-east heroic fan-site data refresh)" } };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// slot: weapon | armor | accessory ; stage: order a new player meets them
const GEAR = [
  { id: 695116, slot: "weapon", line: "tuvala" },
  { id: 10010, slot: "weapon", line: "boss" },
  { id: 715001, slot: "weapon", line: "blackstar" },
  { id: 747206, slot: "weapon", line: "sovereign" },
  { id: 695105, slot: "armor", line: "tuvala" },
  { id: 11013, slot: "armor", line: "boss" },
  { id: 719901, slot: "armor", line: "blackstar" },
  { id: 719897, slot: "armor", line: "origin" },
  { id: 719898, slot: "armor", line: "origin" },
  { id: 12053, slot: "accessory", line: "capotia" },
  { id: 11653, slot: "accessory", line: "deboreka" },
  { id: 12140, slot: "accessory", line: "kharazad" },
  { id: 12142, slot: "accessory", line: "ekleta" },
];

const title = (h) => (h.match(/<title>([^<]*)<\/title>/) || [, ""])[1].replace(/ - BDO Codex$/, "").replace(/&#39;/g, "'").replace(/&amp;/g, "&");

async function page(lang, id) {
  const r = await fetch(`${BASE}/${lang}/item/${id}/`, UA);
  if (!r.ok) throw new Error(`${r.status} ${lang} ${id}`);
  return r.text();
}

function enchantArray(html) {
  const m = html.match(/enchantment_array = (\{.*?\});\s*\n/s) || html.match(/enchantment_array = (\{.*\});/);
  if (!m) return null;
  return JSON.parse(m[1]);
}

const out = { generatedAt: new Date().toISOString(), source: BASE, gear: [], materials: {} };
const icons = new Set();
const matIds = new Set();

for (const g of GEAR) {
  const en = await page("seaen", g.id);
  await sleep(350);
  const th = await page("th", g.id);
  await sleep(350);
  const arr = enchantArray(en);
  const icon = (en.match(/\/items\/new_icon\/[^"']+?\.webp/) || [null])[0];
  if (icon) icons.add(icon);
  const levels = [];
  if (arr) {
    for (const [k, v] of Object.entries(arr)) {
      if (!/^\d+$/.test(k) || !v || typeof v !== "object") continue;
      if (v.need_enchant_item_id) matIds.add(v.need_enchant_item_id);
      levels.push({
        from: Number(k),
        chance: Number(v.enchant_chance),
        material: v.need_enchant_item_id || null,
        count: v.enchant_item_counter ?? null,
        cron: v.cron_value ?? 0,
        failDura: v.fail_dura_dec ?? 0,
        ap: v.damage && v.damage !== "0~0" ? v.damage : null,
        dp: v.defense || null,
      });
    }
  }
  levels.sort((a, b) => a.from - b.from);
  out.gear.push({
    ...g,
    name: { en: title(en), th: title(th) },
    icon,
    url: { en: `${BASE}/seaen/item/${g.id}/`, th: `${BASE}/th/item/${g.id}/` },
    maxLevel: arr?.max_enchant ?? levels.length,
    levels,
  });
  console.log(g.id, title(en), "|", title(th), "levels", levels.length);
}

for (const id of matIds) {
  const en = await page("seaen", id);
  await sleep(350);
  const th = await page("th", id);
  await sleep(350);
  const icon = (en.match(/\/items\/new_icon\/[^"']+?\.webp/) || [null])[0];
  if (icon) icons.add(icon);
  out.materials[id] = {
    name: { en: title(en), th: title(th) },
    icon,
    url: { en: `${BASE}/seaen/item/${id}/`, th: `${BASE}/th/item/${id}/` },
  };
  console.log("material", id, title(en), "|", title(th));
}

for (const p of icons) {
  const dest = path.join(site, "public", "codex", p.replace(/^\/items\//, ""));
  try {
    await fs.access(dest);
    continue;
  } catch {}
  const r = await fetch(BASE + p, UA);
  if (!r.ok) continue;
  await fs.mkdir(path.dirname(dest), { recursive: true });
  await fs.writeFile(dest, Buffer.from(await r.arrayBuffer()));
  await sleep(200);
}

await fs.writeFile(path.join(site, "app", "data", "enhance.json"), JSON.stringify(out, null, 2) + "\n");
console.log("wrote app/data/enhance.json");

// Review step: nothing the AI writes reaches the site until a person approves it.
//
// Usage (from site/):
//   node scripts/patch-watch/approve.ts                 list pending drafts
//   node scripts/patch-watch/approve.ts asia-20041      approve one draft (after reading/editing it)
//   node scripts/patch-watch/approve.ts --reject kr-16442   discard a draft
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { PatchSummary } from "./summarize.ts";

const here = path.dirname(fileURLToPath(import.meta.url));
const siteRoot = path.resolve(here, "../..");
const DRAFTS = path.join(siteRoot, "patch-watch", "drafts");
const FEED = path.join(siteRoot, "app", "data", "patch-feed");

const args = process.argv.slice(2);
const reject = args.includes("--reject");
const id = args.find((a) => !a.startsWith("--"));

async function list() {
  const files = (await fs.readdir(DRAFTS).catch(() => [])).filter((f) => f.endsWith(".json"));
  if (!files.length) return console.log("No pending drafts.");
  for (const f of files.sort()) {
    const d = JSON.parse(await fs.readFile(path.join(DRAFTS, f), "utf8"));
    console.log(`${f.replace(/\.json$/, "").padEnd(14)} [${d.confidence}] ${d.headline?.en ?? d.title}`);
  }
  console.log("\nRead each file in patch-watch/drafts/, fix anything wrong, then approve or reject it.");
}

if (!id) {
  await list();
} else {
  const draftPath = path.join(DRAFTS, `${id}.json`);
  if (reject) {
    await fs.rm(draftPath);
    console.log(`Rejected ${id}`);
  } else {
    const draft = JSON.parse(await fs.readFile(draftPath, "utf8"));
    // Re-validate after manual edits so a broken file never reaches the site.
    PatchSummary.parse(draft);
    const approved = { ...draft, reviewed: true, reviewedAt: new Date().toISOString() };
    delete approved.usage;
    await fs.mkdir(FEED, { recursive: true });
    await fs.writeFile(path.join(FEED, `${id}.json`), JSON.stringify(approved, null, 2) + "\n");
    await fs.rm(draftPath);
    await fs.rm(path.join(DRAFTS, `${id}.extract.txt`), { force: true });
    console.log(`Approved ${id} -> app/data/patch-feed/${id}.json`);
  }
}

import * as cheerio from "cheerio";
import { USER_AGENT, type Source } from "./sources.ts";

export interface ListItem {
  region: Source["region"];
  id: string;
  url: string;
  title: string;
}

export interface Notice extends ListItem {
  published: string | null;
  text: string;
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function get(url: string): Promise<string> {
  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(url, { headers: { "user-agent": USER_AGENT, "accept-language": "en,ko;q=0.8" } });
    if (res.ok) return res.text();
    if (res.status === 404) throw new Error(`404 ${url}`);
    await sleep(2000 * (attempt + 1));
  }
  throw new Error(`fetch failed ${url}`);
}

/** Lists patch-note candidates on a board, newest first, de-duplicated by id. */
export async function listNotices(src: Source): Promise<ListItem[]> {
  const html = await get(src.listUrl);
  const $ = cheerio.load(html);
  const seen = new Map<string, ListItem>();
  $("a[href]").each((_, el) => {
    const href = ($(el).attr("href") ?? "").replace(/&amp;/g, "&");
    src.linkPattern.lastIndex = 0;
    const m = src.linkPattern.exec(`href="${href}"`);
    if (!m) return;
    const id = m[2]!;
    const title = $(el).text().replace(/\s+/g, " ").trim();
    const prev = seen.get(id);
    // The same notice can appear twice (pinned + list); keep the longer title.
    if (!prev || title.length > prev.title.length) seen.set(id, { region: src.region, id, url: m[1]!.replace(/&amp;/g, "&"), title });
  });
  return [...seen.values()]
    .filter((n) => src.include.test(n.title) && !src.exclude.test(n.title))
    .sort((a, b) => Number(b.id) - Number(a.id));
}

/** Fetches a notice and returns its readable text (tables flattened to rows). */
export async function readNotice(item: ListItem): Promise<Notice> {
  const html = await get(item.url);
  const $ = cheerio.load(html);
  const title = $("title").text().split("|")[0]!.trim() || item.title;
  const body = $(".contents_area.editor_area").first();
  body.find("script, style, img, iframe").remove();
  body.find("tr").each((_, tr) => {
    const cells = $(tr).find("th, td").map((__, c) => $(c).text().replace(/\s+/g, " ").trim()).get();
    $(tr).replaceWith(`\n| ${cells.join(" | ")} |\n`);
  });
  body.find("br").replaceWith("\n");
  body.find("p, div, li, h1, h2, h3, h4, h5").each((_, el) => {
    $(el).append("\n");
  });
  const text = body.text().replace(/[ \t]+/g, " ").replace(/\n\s*\n+/g, "\n").trim();
  const dateMatch =
    $(".detail_top_info").text().match(/(\w{3} \d{1,2}, \d{4})|(\d{4}[.-]\d{2}[.-]\d{2})/) ??
    html.match(/(\d{4}\.\d{2}\.\d{2})/);
  return { ...item, title, published: dateMatch ? dateMatch[0] : null, text };
}

