/* E-SAN ADVENTURE design tokens.
   Surface: kram indigo (Isan indigo-dyed cotton). One accent: turmeric saffron. */

:root {
  --font-display: "Chakra Petch", "IBM Plex Sans Thai", system-ui, sans-serif;
  --font-body: "IBM Plex Sans Thai", system-ui, sans-serif;

  --radius: 10px;
  --radius-pill: 999px;

  --z-sticky: 10;
  --z-overlay: 20;

  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);

  /* dark (default) */
  --bg: oklch(0.17 0.035 265);
  --surface: oklch(0.205 0.04 265);
  --surface-2: oklch(0.245 0.045 265);
  --line: oklch(0.33 0.04 265);
  --ink: oklch(0.95 0.01 265);
  --ink-2: oklch(0.79 0.025 265);
  --ink-3: oklch(0.68 0.03 265);
  --accent: oklch(0.79 0.15 68);
  --accent-hover: oklch(0.84 0.14 72);
  --accent-text: oklch(0.82 0.14 70);
  --on-accent: oklch(0.19 0.04 265);
  --accent-soft: oklch(0.79 0.15 68 / 0.14);
  --pattern: oklch(0.95 0.01 265 / 0.045);
  --shadow: 0 20px 50px oklch(0.08 0.04 265 / 0.55);
  color-scheme: dark;
}

:root[data-theme="light"] {
  --bg: oklch(0.975 0.006 265);
  --surface: oklch(0.995 0.003 265);
  --surface-2: oklch(0.945 0.012 265);
  --line: oklch(0.87 0.02 265);
  --ink: oklch(0.22 0.045 265);
  --ink-2: oklch(0.4 0.04 265);
  --ink-3: oklch(0.48 0.035 265);
  --accent: oklch(0.77 0.15 66);
  --accent-hover: oklch(0.72 0.15 62);
  --accent-text: oklch(0.5 0.14 50);
  --on-accent: oklch(0.2 0.045 265);
  --accent-soft: oklch(0.77 0.15 66 / 0.18);
  --pattern: oklch(0.22 0.045 265 / 0.05);
  --shadow: 0 20px 50px oklch(0.4 0.05 265 / 0.16);
  color-scheme: light;
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
    --bg: oklch(0.975 0.006 265);
    --surface: oklch(0.995 0.003 265);
    --surface-2: oklch(0.945 0.012 265);
    --line: oklch(0.87 0.02 265);
    --ink: oklch(0.22 0.045 265);
    --ink-2: oklch(0.4 0.04 265);
    --ink-3: oklch(0.48 0.035 265);
    --accent: oklch(0.77 0.15 66);
    --accent-hover: oklch(0.72 0.15 62);
    --accent-text: oklch(0.5 0.14 50);
    --on-accent: oklch(0.2 0.045 265);
    --accent-soft: oklch(0.77 0.15 66 / 0.18);
    --pattern: oklch(0.22 0.045 265 / 0.05);
    --shadow: 0 20px 50px oklch(0.4 0.05 265 / 0.16);
    color-scheme: light;
  }
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 84px;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

h1,
h2,
h3,
h4 {
  font-family: var(--font-display);
  line-height: 1.15;
  margin: 0;
  text-wrap: balance;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
  text-wrap: pretty;
}

a {
  color: inherit;
}

img {
  display: block;
  max-width: 100%;
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 6px;
}

.container {
  width: 100%;
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 16px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 32px;
  }
}

.num {
  font-family: var(--font-display);
  font-variant-numeric: tabular-nums;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 48px;
  padding: 0 22px;
  border-radius: var(--radius-pill);
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 1rem;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background-color 0.25s var(--ease-out), transform 0.2s var(--ease-out),
    border-color 0.25s var(--ease-out);
}

.btn:active {
  transform: translateY(1px) scale(0.98);
}

.btn-primary {
  background: var(--accent);
  color: var(--on-accent);
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line);
}

.btn-ghost:hover {
  border-color: var(--ink-3);
  background: var(--surface-2);
}

/* ---------- Nav ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: var(--z-sticky);
  background: color-mix(in oklch, var(--bg) 86%, transparent);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid color-mix(in oklch, var(--line) 60%, transparent);
}

.nav-inner {
  height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  text-decoration: none;
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: 0.02em;
  font-size: 1.05rem;
  white-space: nowrap;
}

.brand-mark {
  width: 32px;
  height: 32px;
  flex: none;
}

.nav-links {
  display: none;
  gap: 4px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-links a {
  display: block;
  padding: 8px 14px;
  border-radius: var(--radius-pill);
  text-decoration: none;
  color: var(--ink-2);
  font-size: 0.95rem;
  transition: color 0.2s, background-color 0.2s;
}

.nav-links a:hover {
  color: var(--ink);
  background: var(--surface-2);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.icon-btn {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
}

.icon-btn:hover {
  background: var(--surface-2);
}

.nav-cta {
  display: none;
}

@media (min-width: 960px) {
  .nav-links {
    display: flex;
  }
  .nav-cta {
    display: inline-flex;
    min-height: 42px;
    padding: 0 18px;
  }
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 40px 0 56px;
  overflow: hidden;
}

.hero::before {
  /* mudmee-like woven texture, decorative only */
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(
      45deg,
      var(--pattern) 0 2px,
      transparent 2px 22px
    ),
    repeating-linear-gradient(-45deg, var(--pattern) 0 2px, transparent 2px 22px);
  mask-image: linear-gradient(to bottom, black 0%, transparent 85%);
  pointer-events: none;
}

.hero-grid {
  position: relative;
  display: grid;
  gap: 36px;
  align-items: center;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 0.9rem;
  color: var(--accent-text);
  font-weight: 600;
  margin-bottom: 18px;
}

.hero h1 {
  font-size: clamp(2.2rem, 5.2vw, 4rem);
  font-weight: 700;
  line-height: 1.12;
}

.hero h1 .line {
  display: block;
  white-space: nowrap;
}

.hero h1 em {
  font-style: normal;
  color: var(--accent-text);
}

/* live mini calculator in hero */
.quick {
  position: relative;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--surface);
  box-shadow: var(--shadow);
  padding: 26px;
}

.quick-head {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-weight: 600;
  color: var(--ink);
}

.quick-head svg {
  color: var(--accent-text);
}

.quick-label {
  display: flex;
  justify-content: space-between;
  margin-top: 24px;
  color: var(--ink-2);
  font-size: 0.95rem;
}

.quick-label strong {
  color: var(--ink);
  font-size: 1.1rem;
}

.quick-range {
  width: 100%;
  margin-top: 10px;
  accent-color: var(--accent);
  height: 28px;
  cursor: pointer;
}

.quick-out {
  margin-top: 18px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  color: var(--ink-2);
}

.quick-out strong {
  font-size: clamp(2.6rem, 6vw, 3.6rem);
  line-height: 1;
  color: var(--accent-text);
}

.hero-sub {
  margin-top: 20px;
  font-size: 1.125rem;
  color: var(--ink-2);
  max-width: 46ch;
}

.hero-ctas {
  margin-top: 32px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.hero-visual {
  position: relative;
  border-radius: var(--radius);
  overflow: hidden;
  aspect-ratio: 4 / 3;
  box-shadow: var(--shadow);
  border: 1px solid var(--line);
}

.hero-visual img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(160deg, transparent 40%, oklch(0.17 0.035 265 / 0.55));
}

@media (min-width: 900px) {
  .hero {
    padding: 72px 0 96px;
  }
  .hero-grid {
    grid-template-columns: 1.08fr 0.92fr;
    gap: 56px;
  }
  .hero-visual {
    aspect-ratio: 5 / 6;
  }
}

/* ---------- Stat strip (under hero) ---------- */
.facts {
  border-block: 1px solid var(--line);
  background: var(--surface);
}

.facts-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
}

.fact {
  padding: 22px 16px;
}

.fact + .fact {
  border-left: 1px solid var(--line);
}

.fact:nth-child(3) {
  border-left: none;
}

.fact strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.5rem;
  color: var(--ink);
}

.fact span {
  color: var(--ink-2);
  font-size: 0.92rem;
}

@media (max-width: 767px) {
  .fact:nth-child(n + 3) {
    border-top: 1px solid var(--line);
  }
}

@media (min-width: 768px) {
  .facts-grid {
    grid-template-columns: repeat(4, 1fr);
  }
  .fact:nth-child(3) {
    border-left: 1px solid var(--line);
  }
  .fact {
    padding: 28px 24px;
  }
}

/* ---------- Sections ---------- */
.section {
  padding: 72px 0;
}

@media (min-width: 900px) {
  .section {
    padding: 112px 0;
  }
}

.section-head {
  max-width: 62ch;
  margin-bottom: 40px;
}

.section-head h2 {
  font-size: clamp(1.8rem, 3.6vw, 2.75rem);
  font-weight: 700;
}

.section-head p {
  margin-top: 14px;
  color: var(--ink-2);
  font-size: 1.05rem;
}

@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .reveal {
      animation: reveal-up linear both;
      animation-timeline: view();
      animation-range: entry 0% entry 40%;
    }
  }
}

@keyframes reveal-up {
  from {
    opacity: 0.2;
    transform: translateY(28px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* ---------- Workbench ---------- */
.bench {
  display: grid;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  overflow: hidden;
}

.bench-tabs {
  display: flex;
  gap: 6px;
  padding: 10px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  border-bottom: 1px solid var(--line);
  background: var(--surface-2);
  scrollbar-width: none;
}

.bench-tab {
  position: relative;
  scroll-snap-align: start;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 0;
  border-radius: var(--radius);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--font-body);
  font-size: 0.95rem;
  white-space: nowrap;
  cursor: pointer;
  text-align: left;
}

.bench-tab:hover {
  color: var(--ink);
}

.bench-tab[aria-selected="true"] {
  color: var(--ink);
}

.bench-tab-bg {
  position: absolute;
  inset: 0;
  border-radius: var(--radius);
  background: var(--surface);
  border: 1px solid var(--line);
  z-index: 0;
}

.bench-tab > span,
.bench-tab > svg {
  position: relative;
  z-index: 1;
}

.bench-tab svg {
  color: var(--accent-text);
}

.bench-panel {
  padding: 24px 16px 28px;
  min-height: 420px;
}

@media (min-width: 900px) {
  .bench {
    grid-template-columns: 250px 1fr;
  }
  .bench-tabs {
    flex-direction: column;
    border-bottom: 0;
    border-right: 1px solid var(--line);
    padding: 14px;
    overflow: visible;
  }
  .bench-tab {
    padding: 12px 14px;
  }
  .bench-panel {
    padding: 36px 40px 40px;
  }
}

.calc-title {
  font-size: 1.4rem;
  font-weight: 600;
}

.calc-desc {
  margin-top: 6px;
  color: var(--ink-2);
  max-width: 60ch;
}

.calc-grid {
  margin-top: 28px;
  display: grid;
  gap: 28px;
}

@media (min-width: 1100px) {
  .calc-grid {
    grid-template-columns: 1fr 1fr;
    gap: 40px;
  }
}

.fields {
  display: grid;
  gap: 18px;
  align-content: start;
}

.field {
  display: grid;
  gap: 8px;
}

.field label,
.field .label {
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--ink);
}

.field .help {
  font-size: 0.85rem;
  color: var(--ink-3);
}

.input,
.select {
  width: 100%;
  min-height: 46px;
  padding: 0 14px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-variant-numeric: tabular-nums;
}

.input::placeholder {
  color: var(--ink-3);
}

.input:focus,
.select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.input[aria-invalid="true"] {
  border-color: oklch(0.68 0.19 25);
}

.error {
  font-size: 0.85rem;
  color: oklch(0.72 0.17 25);
}

.row-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.seg {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.seg button {
  min-height: 40px;
  padding: 0 14px;
  border-radius: var(--radius-pill);
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink-2);
  font-family: var(--font-body);
  font-size: 0.92rem;
  cursor: pointer;
}

.seg button[aria-pressed="true"] {
  background: var(--accent);
  color: var(--on-accent);
  border-color: var(--accent);
  font-weight: 600;
}

.toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  cursor: pointer;
}

.toggle input {
  appearance: none;
  flex: none;
  width: 44px;
  height: 26px;
  border-radius: var(--radius-pill);
  background: var(--surface-2);
  border: 1px solid var(--line);
  position: relative;
  cursor: pointer;
  transition: background-color 0.2s;
}

.toggle input::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--ink-3);
  transition: transform 0.25s var(--ease-out), background-color 0.2s;
}

.toggle input:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.toggle input:checked::after {
  transform: translateX(18px);
  background: var(--on-accent);
}

.toggle small {
  display: block;
  color: var(--ink-3);
  font-size: 0.84rem;
}

/* results */
.result {
  border-radius: var(--radius);
  background: var(--bg);
  border: 1px solid var(--line);
  padding: 24px;
  align-self: start;
}

.result-main .k {
  color: var(--ink-2);
  font-size: 0.92rem;
}

